create extension if not exists pgcrypto;create table profiles(id uuid primary key references auth.users(id),full_name text,role text default 'client',is_blocked boolean default false);create table businesses(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id),name text,category text,phone text,about text,status text default 'Active');create table products(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id),name text,price numeric,description text,image_url text);create table services(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id),name text,price numeric,description text,image_url text);create table gallery(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id),image_url text);